#include <stdlib.h>
#include <stdbool.h>

#define MAXM 100005

int next_song[MAXM];
bool visited[MAXM];

int main() {
    int n, m, c;
    if (scanf("%d %d %d", &n, &m, &c) != 3) {
        return 0;
    }

    for (int i = 1; i <= n; i++) {
        int a, d;
        scanf("%d %d", &a, &d);
        if (next_song[d] == 0) {
            next_song[d] = a;
        }
    }

    int current = c;
    int changes = 0;

    while (next_song[current] != 0) {
        if (visited[current]) {
            printf("-1\n");
            return 0;
        }
        visited[current] = true;
        current = next_song[current];
        changes++;
    }

    printf("%d\n", changes);

    return 0;
}
